import React from "react";
import Navbar from "./components/Navbar";
import Hero from "./components/Hero";
import Upload from "./components/Upload";
import Result from "./components/Result";
import Footer from "./components/Footer";
import "./App.css";

function App() {
  return (
    <div className="app-container">

      {/* Colorful Fish */}

      <img
        className="fish fish1"
        src="https://cdn-icons-png.flaticon.com/512/3069/3069172.png"
        alt="fish"
      />

      <img
        className="fish fish2"
        src="https://cdn-icons-png.flaticon.com/512/616/616430.png"
        alt="fish"
      />

      <img
        className="fish fish3"
        src="https://cdn-icons-png.flaticon.com/512/1998/1998627.png"
        alt="fish"
      />

      <img
        className="fish fish4"
        src="https://cdn-icons-png.flaticon.com/512/3069/3069172.png"
        alt="fish"
      />

      <img
        className="fish fish5"
        src="https://cdn-icons-png.flaticon.com/512/616/616408.png"
        alt="fish"
      />

      <Navbar />
      <Hero />
      <Upload />
      <Result />
      <Footer />

    </div>
  );
}

export default App;
